INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destrobots', 'Destrobots is an easy-to-play, hard-to-master top-down shooter that will make every party a blast. Three core actions of Move – Spin – Shoot make for an explosive combination that ensures every match is fast-paced, challenging, and fun. Watch out for traps or exploit them against your opponents, be quick to hunt down scales-tipping power-ups, and forget the words “fair play”. Sharpen your reflexes so you can dance between enemy laser beams, land your own shots, and grab that sweet victory!' FROM games WHERE igdb_id = 135656 ON CONFLICT (game_id, language_code) DO NOTHING;
