INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missing Features: 2D', 'Missing Features: 2D is a platformer game that, as the name implies, the features are missing! Look how crazy! You discovered this game left on your computer and out of curiosity and free from fear of blowing up your PC, you decided to install it. The game did not install correctly (obviously) and now you need to play and install the missing features.' FROM games WHERE igdb_id = 141331 ON CONFLICT (game_id, language_code) DO NOTHING;
