INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Riding Stables 2: A New Adventure', 'Run your own riding stable full of horses and take good care of your animals and your guests. Ride freely around the open game world, through a wide variety of landscapes. The riding controls are intuitive. Speed, skill and courage are required for the mounted games – riding games that are both thrilling and fun! Train hard and claim victory in the tournament!' FROM games WHERE igdb_id = 140008 ON CONFLICT (game_id, language_code) DO NOTHING;
