INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rose & Camellia: The Legendary Rose Bride', 'A remake of the 2007 Flash game by Nigoro, optimized for smartphones and touchscreen controls. Play as the recently widowed Reiko, as you slap-duel your way through the Tsubakikoji family and establish your place as the matriarch. Fighting is turn-based, and timing-based, reminiscent of other fighting games such as Punch-Out!! A short little game by the makers of La-Mulana about the elegant art of feminine conflict.' FROM games WHERE igdb_id = 227726 ON CONFLICT (game_id, language_code) DO NOTHING;
